/* UTP Cafeteria Batch Advisor - dashboard logic.
 * All model data comes from data/dashboard_data.js, generated by src/train_model.py.
 * The decision tree trained in Python is re-run here node-by-node, so the browser
 * makes exactly the same prediction as the scikit-learn model.
 */
(function () {
  "use strict";
  const D = window.DASHBOARD_DATA;
  if (!D) { document.body.innerHTML = "<p style='padding:40px'>dashboard_data.js missing - run <code>python src/run_all.py</code>.</p>"; return; }

  const S = D.survey, M = S.multipliers, CFG = D.settings, TREE = D.tree;
  const $ = (id) => document.getElementById(id);
  const fmt = (n, d = 0) => Number(n).toLocaleString("en-MY", { maximumFractionDigits: d, minimumFractionDigits: d });
  const COLORS = { Low: "#1e8e5a", Medium: "#d98a1c", High: "#c0392b", brand: "#1f5f8b", grey: "#9aa5b1" };
  const SOFT = { Low: "#e3f4eb", Medium: "#fdf1df", High: "#fbe5e2" };
  const DAY_FULL = { Mon: "Monday", Tue: "Tuesday", Wed: "Wednesday", Thu: "Thursday", Fri: "Friday", Sat: "Saturday", Sun: "Sunday" };
  const ICONS = { Lunch: "🍛", Dinner: "🌙", "Normal week": "📘", "Exam week": "📝", "Holiday / break": "🏖️", Clear: "☀️", "Heavy rain": "🌧️", Haze: "🌫️" };
  const SHORT = { "Normal week": "Normal", "Exam week": "Exam", "Holiday / break": "Holiday" };

  const state = { day: "Wed", meal: "Lunch", calendar: "Normal week", weather: "Clear", shortBreak: false, batch: 120 };

  /* ------------------------------------------------------------------ model */
  function encode(s) {
    return {
      is_friday: +(s.day === "Fri"),
      is_weekend: +(s.day === "Sat" || s.day === "Sun"),
      exam_week: +(s.calendar === "Exam week"),
      holiday: +(s.calendar === "Holiday / break"),
      heavy_rain: +(s.weather === "Heavy rain"),
      haze: +(s.weather === "Haze"),
      short_break: +s.shortBreak,
      is_lunch: +(s.meal === "Lunch"),
    };
  }

  // Same formula as src/build_dataset.py -> expected_demand()
  function demand(s) {
    const f = [];
    if (s.day === "Fri") f.push(["Friday", M.friday]);
    else if (s.day === "Sat" || s.day === "Sun") f.push(["Weekend", M.weekend]);
    if (s.calendar === "Exam week") f.push(["Exam week", M.exam_week]);
    else if (s.calendar === "Holiday / break") f.push(["Holiday / break", M.holiday]);
    if (s.weather === "Heavy rain") f.push(["Heavy rain", M.heavy_rain]);
    else if (s.weather === "Haze") f.push(["Haze", M.haze]);
    const breakApplies = s.shortBreak && s.meal === "Lunch" && !["Sat", "Sun"].includes(s.day) && s.calendar !== "Holiday / break";
    if (breakApplies) f.push(["Short class breaks", M.short_break]);
    const raw = f.reduce((a, [, m]) => a * m, 1);
    return { value: Math.max(raw, CFG.demand_floor), raw, factors: f, floored: raw < CFG.demand_floor };
  }

  function predict(features) {
    const nodes = TREE.nodes, path = [];
    let i = 0;
    while (nodes[i].left !== -1) {
      const n = nodes[i], x = features[n.feature], goRight = x > n.threshold;
      path.push({ feature: n.feature, yes: !!x, samples: n.samples });
      i = goRight ? n.right : n.left;
    }
    const probs = nodes[i].probs;
    let best = 0;
    probs.forEach((p, k) => { if (p > probs[best]) best = k; });
    return { tier: TREE.classes[best], confidence: probs[best], probs, path, leafSamples: nodes[i].samples };
  }

  function assumptions() {
    const v = (id, d) => { const x = parseFloat($(id).value); return isFinite(x) && x >= 0 ? x : d; };
    return { kg: v("a-kg", 0.35), rm: v("a-rm", 4), kwh: v("a-kwh", 0.4), warm: v("a-warm", 1.5), hrs: v("a-hrs", 2), co2: v("a-co2", 0.58) };
  }

  /* ------------------------------------------------------------- controls */
  function buildControls() {
    const chips = $("day-chips");
    CFG.days.forEach((d) => {
      const b = document.createElement("button");
      b.className = "chip"; b.textContent = d; b.dataset.val = d; b.type = "button";
      b.onclick = () => { state.day = d; render(); };
      chips.appendChild(b);
    });
    const seg = (el, key, opts) => opts.forEach((o) => {
      const b = document.createElement("button");
      b.className = "seg-btn"; b.type = "button"; b.dataset.val = o;
      b.innerHTML = `<span class="ico">${ICONS[o] || ""}</span><span>${SHORT[o] || o}</span>`;
      b.onclick = () => { state[key] = o; render(); };
      $(el).appendChild(b);
    });
    seg("meal-seg", "meal", CFG.meals);
    seg("cal-seg", "calendar", CFG.calendar);
    seg("wx-seg", "weather", CFG.weather);

    $("short-break").onchange = (e) => { state.shortBreak = e.target.checked; render(); };
    const setBatch = (v) => { state.batch = Math.max(1, Math.min(2000, Math.round(v) || 1)); render(); };
    $("batch-range").oninput = (e) => setBatch(+e.target.value);
    $("batch").oninput = (e) => setBatch(+e.target.value);
    ["a-kg", "a-rm", "a-kwh", "a-warm", "a-hrs", "a-co2"].forEach((id) => { $(id).oninput = render; });
    $("cafe").onchange = render;
  }

  function syncControls() {
    document.querySelectorAll("#day-chips .chip").forEach((b) => b.classList.toggle("active", b.dataset.val === state.day));
    [["meal-seg", "meal"], ["cal-seg", "calendar"], ["wx-seg", "weather"]].forEach(([el, k]) =>
      document.querySelectorAll(`#${el} .seg-btn`).forEach((b) => b.classList.toggle("active", b.dataset.val === state[k])));
    $("short-break").checked = state.shortBreak;
    if (+$("batch").value !== state.batch) $("batch").value = state.batch;
    $("batch-range").value = Math.min(400, state.batch);
  }

  /* --------------------------------------------------------------- render */
  let slotChart;

  function render() {
    syncControls();
    const dem = demand(state), pred = predict(encode(state)), A = assumptions();
    const tier = pred.tier, pct = Math.round(dem.value * 100);
    const root = document.documentElement.style;
    root.setProperty("--risk", COLORS[tier]);
    root.setProperty("--risk-soft", SOFT[tier]);

    // Headline
    $("scenario-title").textContent = `${$("cafe").value} · ${DAY_FULL[state.day]} ${state.meal.toLowerCase()} · ${state.calendar} · ${state.weather}` + (state.shortBreak && state.meal === "Lunch" ? " · short breaks" : "");
    $("risk-tier").textContent = tier;
    $("risk-msg").textContent = {
      Low: "Customer numbers should be close to a normal day. Cook as usual and keep the normal warmer schedule.",
      Medium: "Expect noticeably fewer customers. Cook a smaller first batch and top up only if it sells.",
      High: "Expect far fewer customers than usual. Cook a small first batch and cook more only when needed.",
    }[tier];
    $("demand-pct").textContent = pct;
    const arc = 157.1;
    $("gauge-fg").style.strokeDasharray = arc;
    $("gauge-fg").style.strokeDashoffset = arc * (1 - Math.min(dem.value, 1));
    $("conf-bar").style.width = Math.round(pred.confidence * 100) + "%";
    $("conf-pct").textContent = Math.round(pred.confidence * 100) + "%";

    // KPIs
    const rec = Math.round(state.batch * dem.value);
    const lo = Math.round(rec * 0.9), hi = Math.min(state.batch, Math.round(rec * 1.1));
    const saved = state.batch - rec;
    const warmerKwh = tier === "High" ? A.warm * A.hrs : tier === "Medium" ? A.warm * A.hrs * 0.5 : 0;
    const kwh = saved * A.kwh + warmerKwh;
    $("kpi-rec").textContent = fmt(rec);
    $("kpi-range").textContent = `portions · range ${fmt(lo)} – ${fmt(hi)}`;
    $("kpi-saved").textContent = fmt(saved);
    $("kpi-kg").textContent = fmt(saved * A.kg, 1) + " kg";
    $("kpi-rm").textContent = `≈ RM ${fmt(saved * A.rm)} ingredient cost`;
    $("kpi-kwh").textContent = fmt(kwh, 1) + " kWh";
    $("kpi-co2").textContent = `≈ ${fmt(kwh * A.co2, 1)} kg CO₂ · cooking + warmers`;

    renderPlan(tier, rec);
    renderWhy(dem, pred);
    renderSlots(dem);
    renderWeek();
    renderTips();
  }

  function renderPlan(tier, rec) {
    const lunch = state.meal === "Lunch";
    const t = lunch
      ? { prep: "By 11:30 AM", peak: "12:30 PM check", late: "After 2:30 PM" }
      : { prep: "By 5:30 PM", peak: "7:30 PM check", late: "After 9:00 PM" };
    const first = { Low: rec, Medium: Math.round(rec * 0.8), High: Math.round(rec * 0.6) }[tier];
    const topUp = Math.max(rec - first, 0);
    const lunchLate = S.lunch_time["After 2:00 pm"].pct;
    const steps = {
      Low: [
        [t.prep, `Cook the full first batch of <strong>${first} portions</strong>.`],
        [t.peak, lunch ? `Normal rush expected — ${S.lunch_time["12:00 to 1:00 pm"].pct}% of lunch customers arrive 12–1 PM.` : "Normal dinner rush expected."],
        [t.late, lunch ? `Keep warmers on: ${lunchLate}% of students eat lunch after 2 PM. Switch to low heat after 3:00 PM.` : "Reduce warmers to low heat once the dinner rush ends."],
      ],
      Medium: [
        [t.prep, `Cook <strong>${first} portions</strong> first. Prepare (but don't cook) ingredients for ${topUp} more.`],
        [t.peak, `If more than half has sold, cook the <strong>${topUp}-portion top-up</strong>. If not, skip it.`],
        [t.late, "Combine leftover dishes into fewer warmer wells, switch off the empty wells and run the exhaust hood on low."],
      ],
      High: [
        [t.prep, `Cook a small first batch of <strong>${first} portions</strong> only.`],
        [t.peak, `Cook small top-ups (≈${Math.max(Math.round(state.batch * 0.1), 1)} portions) only when a tray is below a quarter full — up to ${topUp} more in total.`],
        [t.late, "Switch off unused warmer wells and turn the exhaust hood to its lowest setting. This cuts idle gas and electricity."],
      ],
    }[tier];
    $("plan").innerHTML = steps.map(([time, txt]) => `<li><span class="time">${time}</span>${txt}</li>`).join("");
  }

  function renderWhy(dem, pred) {
    const rows = [["Normal weekday", 1], ...dem.factors];
    let html = rows.map(([lbl, m]) => `
      <div class="factor"><span>${lbl}</span><div class="fbar"><div style="width:${Math.min(m, 1) * 100}%"></div></div>
      <span class="fv">${lbl === "Normal weekday" ? "100%" : "×" + m.toFixed(2)}</span></div>`).join("");
    html += `<div class="factor total"><span>Expected demand${dem.floored ? " (floor)" : ""}</span><div class="fbar"><div style="width:${dem.value * 100}%"></div></div><span class="fv">${Math.round(dem.value * 100)}%</span></div>`;
    $("factors").innerHTML = html;

    const L = CFG.feature_labels;
    const steps = pred.path.map((p) => `<li>${L[p.feature].replace(/ \(.*\)/, "")}? <span class="${p.yes ? "yes" : "no"}">${p.yes ? "Yes" : "No"}</span></li>`);
    steps.push(`<li class="leaf">→ <span style="color:${COLORS[pred.tier]}">${pred.tier} risk</span> <span class="muted small">(${Math.round(pred.confidence * 100)}% of ${pred.leafSamples} similar training days)</span></li>`);
    $("path").innerHTML = steps.join("");
  }

  function renderSlots(dem) {
    let labels, normal, scen, note;
    if (state.meal === "Lunch") {
      const lt = S.lunch_time;
      labels = ["Before 12 PM", "12–1 PM", "1–2 PM", "After 2 PM"];
      const shares = ["Before 12:00 pm", "12:00 to 1:00 pm", "1:00 to 2:00 pm", "After 2:00 pm"].map((k) => lt[k].pct / 100);
      normal = shares.map((s) => Math.round(state.batch * s));
      scen = shares.map((s) => Math.round(state.batch * dem.value * s));
      note = "Lunch timing from survey Q5";
    } else {
      labels = ["Whole dinner service"];
      normal = [state.batch];
      scen = [Math.round(state.batch * dem.value)];
      note = "Dinner timing was not surveyed — total only";
    }
    $("slot-note").textContent = note;
    const tier = predict(encode(state)).tier;
    const data = {
      labels,
      datasets: [
        { label: "Normal weekday", data: normal, backgroundColor: "#cfd8e3", borderRadius: 6 },
        { label: "This scenario", data: scen, backgroundColor: COLORS[tier], borderRadius: 6 },
      ],
    };
    if (slotChart) { slotChart.data = data; slotChart.update(); return; }
    slotChart = new Chart($("slot-chart"), {
      type: "bar", data,
      options: baseOpts({ y: { title: { display: true, text: "Expected customers" } } }),
    });
  }

  function renderWeek() {
    const el = $("week");
    el.innerHTML = "";
    CFG.days.forEach((d) => {
      const s = { ...state, day: d };
      const dm = demand(s), p = predict(encode(s));
      const b = document.createElement("button");
      b.type = "button";
      b.className = "wday" + (d === state.day ? " sel" : "");
      b.innerHTML = `<div class="d">${d}</div><div class="p">${Math.round(dm.value * 100)}%</div><span class="t t-${p.tier}">${p.tier}</span>`;
      b.onclick = () => { state.day = d; render(); };
      el.appendChild(b);
    });
    $("week-note").textContent = `${state.calendar} · ${state.weather} · ${state.meal} · click a day`;
  }

  function renderTips() {
    const pct = (o, k) => (o[k] ? o[k].pct : 0);
    const tips = [];
    if (state.weather === "Heavy rain")
      tips.push(["☔", "Rain plan", `${Math.round(pct(S.dining_mode, "Both equally") + pct(S.dining_mode, "Takeaway"))}% of students sometimes take away. Have containers ready for students who dash in and out.`]);
    if (state.weather === "Haze")
      tips.push(["🌫️", "Haze plan", "Students stay indoors more on hazy days. Keep the menu shorter and push takeaway."]);
    if (state.calendar === "Holiday / break")
      tips.push(["🏖️", "Break week", `Only ${Math.round(M.holiday * 100)}% of students stay on campus during breaks. Offer a short menu with your 2–3 best sellers.`]);
    if (state.calendar === "Exam week")
      tips.push(["📝", "Exam week", "Students stay in to study. Food that is quick to take away sells better than full dine-in meals."]);
    if (state.shortBreak && state.meal === "Lunch")
      tips.push(["⏱️", "Short breaks", `${pct(S.short_break, "Eat before or after class")}% eat before or after class instead. Expect small rushes before 12 and after 2 PM.`]);
    const portion = pct(S.leave_reason, "Ordered too much") + pct(S.leave_reason, "Portion too big");
    tips.push(["🍽️", "Smaller portion option", `"Ordered too much" and "portion too big" make up ${Math.round(portion)}% of the reasons students leave food. A half-portion option cuts plate waste.`]);
    const shift = pct(S.forecast_reaction, "Eat somewhere else") + pct(S.forecast_reaction, "Eat earlier or later");
    tips.push(["📣", "Share quiet hours", `${Math.round(shift)}% of students would change when or where they eat if told it's busy. Posting quiet times spreads demand more evenly.`]);
    $("tips").innerHTML = tips.slice(0, 4).map(([i, t, d]) => `<div class="tip"><span class="ti">${i}</span><div><strong>${t}</strong>${d}</div></div>`).join("");
  }

  /* ----------------------------------------------------------- charts util */
  function baseOpts(scales = {}, extra = {}) {
    return {
      responsive: true, maintainAspectRatio: false,
      plugins: { legend: { position: "bottom", labels: { boxWidth: 12, usePointStyle: true } }, ...(extra.plugins || {}) },
      scales: {
        x: { grid: { display: false }, ...(scales.x || {}) },
        y: { grid: { color: "#eef1f5" }, beginAtZero: true, ...(scales.y || {}) },
      },
      indexAxis: extra.indexAxis || "x",
    };
  }
  const pctTick = { callback: (v) => v + "%" };
  function hbar(id, obj, color, opts = {}) {
    const labels = Object.keys(obj), vals = labels.map((k) => obj[k].pct);
    return new Chart($(id), {
      type: "bar",
      data: { labels, datasets: [{ data: vals, backgroundColor: color, borderRadius: 5 }] },
      options: {
        ...baseOpts({ x: { grid: { color: "#eef1f5" }, ticks: pctTick, beginAtZero: true, max: opts.max }, y: { grid: { display: false } } }, { indexAxis: "y" }),
        plugins: { legend: { display: false }, tooltip: { callbacks: { label: (c) => `${c.parsed.x}% (${obj[c.label].count} students)` } } },
      },
    });
  }

  /* ------------------------------------------------------------- insights */
  let insightsBuilt = false;
  function buildInsights() {
    if (insightsBuilt) return;
    insightsBuilt = true;

    const multLabels = { exam_week: "Exam week", friday: "Friday", haze: "Hazy day", weekend: "Weekend", short_break: "Short breaks (lunch)", heavy_rain: "Heavy rain", holiday: "Holiday / break" };
    const keys = Object.keys(multLabels).sort((a, b) => M[b] - M[a]);
    const vals = keys.map((k) => Math.round(M[k] * 100));
    const th = CFG.risk_thresholds;
    new Chart($("ch-mult"), {
      type: "bar",
      data: {
        labels: ["Normal weekday", ...keys.map((k) => multLabels[k])],
        datasets: [{ data: [100, ...vals], borderRadius: 5,
          backgroundColor: [COLORS.grey, ...vals.map((v) => v >= th.Low * 100 ? COLORS.Low : v >= th.Medium * 100 ? COLORS.Medium : COLORS.High)] }],
      },
      options: {
        ...baseOpts({ x: { grid: { color: "#eef1f5" }, ticks: pctTick, max: 100 }, y: { grid: { display: false } } }, { indexAxis: "y" }),
        plugins: { legend: { display: false }, tooltip: { callbacks: { label: (c) => `${c.parsed.x}% of normal-day demand` } } },
      },
    });

    const lk = { exam_week: "Exam week", friday: "Friday", weekend: "Weekend", haze: "Haze", heavy_rain: "Heavy rain" };
    const levels = ["Very unlikely", "Somewhat unlikely", "Neither likely nor unlikely", "Somewhat likely", "Very likely"];
    const lkColors = ["#c0392b", "#e59866", "#d5d8dc", "#7fb3d5", "#1f5f8b"];
    new Chart($("ch-likert"), {
      type: "bar",
      data: {
        labels: Object.values(lk),
        datasets: levels.map((lv, i) => ({ label: lv.replace(" nor unlikely", ""), data: Object.keys(lk).map((k) => S.likert[k][lv].pct), backgroundColor: lkColors[i] })),
      },
      options: {
        ...baseOpts({ x: { stacked: true, max: 100, ticks: pctTick, grid: { color: "#eef1f5" } }, y: { stacked: true, grid: { display: false } } }, { indexAxis: "y" }),
        plugins: { legend: { position: "bottom", labels: { boxWidth: 10, font: { size: 11 } } }, tooltip: { callbacks: { label: (c) => `${c.dataset.label}: ${c.parsed.x}%` } } },
      },
    });

    hbar("ch-lunch", S.lunch_time, COLORS.brand);
    hbar("ch-meals", S.meals, COLORS.brand, { max: 100 });
    hbar("ch-days", S.days_per_week, COLORS.brand);
    hbar("ch-break", S.short_break, "#2a7aa8");
    const reasons = Object.fromEntries(Object.entries(S.leave_reason).sort((a, b) => b[1].pct - a[1].pct));
    hbar("ch-reason", reasons, "#e07a2f");
    hbar("ch-forecast", S.forecast_reaction, "#2a7aa8");
    hbar("ch-village", S.residence, "#5d8aa8");
    hbar("ch-year", S.year, "#5d8aa8");
  }

  function fillStats() {
    document.querySelectorAll('[data-bind="n"]').forEach((e) => (e.textContent = S.n));
    const lr = S.likert.heavy_rain;
    $("st-rain").textContent = Math.round(lr["Very unlikely"].pct + lr["Somewhat unlikely"].pct) + "%";
    $("st-holiday").textContent = Math.round(S.holiday_stay.Never.pct + S.holiday_stay.Rarely.pct) + "%";
    $("st-plate").textContent = Math.round(S.leave_food.Never.pct + S.leave_food.Rarely.pct) + "%";
    $("st-forecast").textContent = Math.round(S.forecast_reaction["Eat somewhere else"].pct + S.forecast_reaction["Eat earlier or later"].pct) + "%";
    $("gen-date").textContent = D.generated;
  }

  /* ---------------------------------------------------------------- model */
  let modelBuilt = false;
  function buildModel() {
    if (modelBuilt) return;
    modelBuilt = true;
    const mt = D.metrics;
    $("m-acc").textContent = Math.round(mt.test_accuracy * 1000) / 10 + "%";
    $("m-agree").textContent = Math.round(mt.agreement_with_survey_rule * 1000) / 10 + "%";
    $("m-leaves").textContent = mt.tree_leaves;
    $("m-depth").textContent = mt.tree_depth;
    $("m-rows").textContent = fmt(mt.train_rows + mt.test_rows);

    const imp = Object.entries(mt.feature_importance).sort((a, b) => b[1] - a[1]);
    new Chart($("ch-imp"), {
      type: "bar",
      data: { labels: imp.map(([k]) => CFG.feature_labels[k]), datasets: [{ data: imp.map(([, v]) => Math.round(v * 1000) / 10), backgroundColor: COLORS.brand, borderRadius: 5 }] },
      options: { ...baseOpts({ x: { grid: { color: "#eef1f5" }, ticks: pctTick }, y: { grid: { display: false } } }, { indexAxis: "y" }), plugins: { legend: { display: false } } },
    });

    const cm = mt.confusion_matrix, max = Math.max(...cm.matrix.flat());
    let html = `<div class="h"></div>` + cm.labels.map((l) => `<div class="h">${l}</div>`).join("");
    cm.matrix.forEach((row, i) => {
      html += `<div class="h">${cm.labels[i]}</div>`;
      row.forEach((v, j) => {
        const a = 0.08 + 0.8 * (v / max);
        const bg = i === j ? `rgba(31,95,139,${a})` : v ? `rgba(192,57,43,${0.1 + 0.5 * v / max})` : "#f6f8fa";
        html += `<div class="c" style="background:${bg};color:${a > .5 && i === j ? "#fff" : "inherit"}">${v}</div>`;
      });
    });
    $("cm").innerHTML = html;

    const tb = $("tests");
    tb.innerHTML = `<thead><tr><th>Scenario</th><th>Meal</th><th>Calendar</th><th>Weather</th><th class="num">Demand</th><th>AI risk</th><th class="num">Confidence</th><th class="num">Cook (of 100)</th></tr></thead><tbody>` +
      D.test_scenarios.map((t, i) => `<tr data-i="${i}"><td><strong>${t.scenario}</strong></td><td>${t.meal}</td><td>${t.calendar}</td><td>${t.weather}${t.short_break ? " · short breaks" : ""}</td><td class="num">${t.expected_demand_pct}%</td><td><span class="t t-${t.predicted_risk}">${t.predicted_risk}</span></td><td class="num">${t.confidence_pct}%</td><td class="num">${t.recommended_batch_if_usual_100}</td></tr>`).join("") + "</tbody>";
    tb.querySelectorAll("tbody tr").forEach((tr) => tr.onclick = () => {
      const t = D.test_scenarios[+tr.dataset.i];
      Object.assign(state, { day: t.day, meal: t.meal, calendar: t.calendar, weather: t.weather, shortBreak: t.short_break, batch: 100 });
      showTab("predict"); render();
      window.scrollTo({ top: 0, behavior: "smooth" });
    });

    $("m-base").textContent = S.baseline_weekday_probability;
    $("m-floor").textContent = Math.round(CFG.demand_floor * 100);
    $("m-low").textContent = Math.round(CFG.risk_thresholds.Low * 100);
    $("m-med").textContent = Math.round(CFG.risk_thresholds.Medium * 100);
  }

  /* ----------------------------------------------------------------- tabs */
  function showTab(name) {
    document.querySelectorAll(".tab").forEach((t) => t.classList.toggle("active", t.dataset.tab === name));
    document.querySelectorAll(".tab-panel").forEach((p) => p.classList.toggle("active", p.id === "tab-" + name));
    if (name === "insights") buildInsights();
    if (name === "model") buildModel();
  }

  /* ----------------------------------------------------------------- init */
  if (window.Chart) {
    Chart.defaults.font.family = "Inter, system-ui, sans-serif";
    Chart.defaults.color = "#637083";
  } else {
    window.Chart = function () { return { update() {} }; }; // offline fallback: skip charts
  }
  document.querySelectorAll(".tab").forEach((t) => (t.onclick = () => showTab(t.dataset.tab)));
  buildControls();
  fillStats();
  buildModel(); // assumption inputs live in the model tab and are read by render()
  render();
})();
